#!/usr/bin/env python3
"""A tiny stub MCP server for exercising LLMFlow-Search's generic profile by hand.

It exposes one trivial tool (`get_fact`) and nothing footnote-specific, so connecting
LLMFlow-Search to it forces the generic profile. Drive the agent against it with:

    LLMFLOW_SEARCH_MCP_CMD="python scripts/stub_mcp_server.py" PYTHONPATH=src python -m llmflow_search

then ask e.g. "what is the capital of France?".
"""
import asyncio

from mcp.server import Server
from mcp.server.models import InitializationOptions
from mcp.server.stdio import stdio_server
from mcp.types import ServerCapabilities, TextContent, Tool

server = Server("stub")

_FACTS = {
    "capital of france": "The capital of France is Paris.",
    "speed of light": "The speed of light in vacuum is 299,792,458 metres per second.",
    "tallest mountain": "Mount Everest is the tallest mountain above sea level, at 8,849 metres.",
}


@server.list_tools()
async def list_tools() -> list[Tool]:
    return [
        Tool(
            name="get_fact",
            description="Look up a short, sourced factual statement about a topic.",
            inputSchema={
                "type": "object",
                "properties": {
                    "topic": {"type": "string", "description": "Topic to look up"}
                },
                "required": ["topic"],
            },
        )
    ]


@server.call_tool()
async def call_tool(name: str, arguments: dict) -> list[TextContent]:
    if name == "get_fact":
        topic = (arguments.get("topic") or "").strip().lower()
        fact = next((v for k, v in _FACTS.items() if k in topic or topic in k), None)
        return [
            TextContent(type="text", text=fact or f"No fact on file for '{topic}'.")
        ]
    return [TextContent(type="text", text=f"unknown tool: {name}")]


async def _main():
    init = InitializationOptions(
        server_name="stub",
        server_version="0.1.0",
        capabilities=ServerCapabilities(tools={}),
    )
    async with stdio_server() as (read, write):
        await server.run(read, write, init)


if __name__ == "__main__":
    asyncio.run(_main())

"""Pure production routing decisions for the research graph."""

from .config import (
    INSUFFICIENT_EVIDENCE_MESSAGE,
    MAX_EVIDENCE_ROUNDS,
    MAX_PLAN_STEPS,
    MAX_STAGNANT_ROUNDS,
)
from .search_memory import _merge_search_memory
from .state import AgentState


def route_after_execute(state: AgentState) -> str:
    """Route after each execute step — update the evidence ledger when plan is exhausted."""
    plan = state["plan"]
    completed = state["completed_steps"]
    if len(completed) >= MAX_PLAN_STEPS:
        return "evidence_ledger"
    if not plan:
        return "evidence_ledger"
    return "execute"


def route_after_evidence_ledger(state: AgentState) -> str:
    if state.get("evidence_audit", {}).get("dedup_stalled"):
        return "evidence_reextract"
    return "evidence_challenge"


def route_after_evidence_reextract(state: AgentState) -> str:
    audit = state.get("evidence_audit", {})
    if audit and audit.get("passed"):
        return "evidence_challenge"
    if state.get("sources"):
        return "answer"
    return "assimilate"


def route_after_evidence_challenge(state: AgentState) -> str:
    audit = state.get("evidence_audit", {})
    if audit.get("dedup_stalled"):
        return "evidence_reextract"
    if audit and audit.get("passed"):
        return "answer"
    verification = state.get("verification_result", {})
    if (
        verification.get("insufficient_evidence") is True
        and state.get("final_answer") == INSUFFICIENT_EVIDENCE_MESSAGE
        and not state.get("plan")
    ):
        return "answer" if state.get("sources") else "assimilate"
    if state.get("plan") and len(state.get("completed_steps", [])) < MAX_PLAN_STEPS:
        return "execute"
    if (
        state.get("evidence_round", 0) <= MAX_EVIDENCE_ROUNDS
        and len(state.get("completed_steps", [])) < MAX_PLAN_STEPS
        and state.get("stagnant_rounds", 0) < MAX_STAGNANT_ROUNDS
    ):
        return "strategy"
    # The search budget is exhausted. Supported ledger sources can still produce a
    # useful, explicitly incomplete answer; only a run with no admissible evidence
    # should terminate with the insufficient-evidence message alone.
    return "answer" if state.get("sources") else "assimilate"


def route_after_plan(state: AgentState) -> str:
    search_memory = _merge_search_memory(state.get("search_memory"))
    if (
        search_memory.get("search_exhausted")
        and state.get("final_answer") == INSUFFICIENT_EVIDENCE_MESSAGE
    ):
        return "answer" if state.get("sources") else "assimilate"
    if state["plan"]:
        return "execute"
    return "answer"


def route_after_verify(state: AgentState) -> str:
    final_answer = state.get("final_answer", "")
    draft = (
        state.get("draft_result", {})
        if isinstance(state.get("draft_result"), dict)
        else {}
    )

    has_real_answer = (
        bool(final_answer) and final_answer != INSUFFICIENT_EVIDENCE_MESSAGE
    )
    draft_answer = draft.get("answer", "") if isinstance(draft, dict) else ""
    has_valid_draft = (
        bool(draft_answer)
        and draft_answer != INSUFFICIENT_EVIDENCE_MESSAGE
        and not draft.get("insufficient_evidence")
        and bool(state.get("sources"))
    )

    if has_real_answer or has_valid_draft:
        return "assimilate"

    search_memory = _merge_search_memory(state.get("search_memory"))
    if search_memory.get("search_exhausted"):
        return "assimilate"

    if not state.get("sources"):
        if (
            state.get("evidence_round", 0) <= MAX_EVIDENCE_ROUNDS
            and len(state.get("completed_steps", [])) < MAX_PLAN_STEPS
            and state.get("stagnant_rounds", 0) < MAX_STAGNANT_ROUNDS
        ):
            return "strategy"
    return "assimilate"

"""Does the object a model returned actually match the schema it was given?

Ollama's ``format=<schema>`` argument is a request, not a guarantee. Only the
GGUF/llama.cpp decoder enforces it; the MLX runtime ignores it (see
``llm._schema_capable_model``) and so does every ``:cloud`` model, which is served by a
remote API that receives the messages and drops the schema. On those backends a caller
that passes a schema gets ordinary free-running generation and no error, so a
malformed evidence ledger looks exactly like an empty one — the run degrades quietly
into "no supported claims" and the trace records nothing about why.

This module makes that failure observable and fixable without a backend: a checker
strict enough to catch the shapes the pipeline's normalizers silently discard, and a
rendering of the schema that can be put in the prompt where an unenforcing backend will
at least read it.

Deliberately not a full JSON Schema implementation. It covers the constructs this
codebase's schemas actually use — object/array/string/integer/number/boolean types,
``required``, ``enum``, ``additionalProperties: false`` and integer bounds — and ignores
the rest rather than pretending to validate it.
"""

from typing import Any

_TYPE_CHECKS: dict[str, Any] = {
    "object": lambda v: isinstance(v, dict),
    "array": lambda v: isinstance(v, list),
    "string": lambda v: isinstance(v, str),
    "boolean": lambda v: isinstance(v, bool),
    # JSON has one number type and bool is an int in Python; both distinctions matter
    # here, because a ledger row's requirement_index is an array position.
    "integer": lambda v: isinstance(v, int) and not isinstance(v, bool),
    "number": lambda v: isinstance(v, (int, float)) and not isinstance(v, bool),
}

MAX_VIOLATIONS = 20


def schema_violations(value: Any, schema: dict, path: str = "$") -> list[str]:
    """Every way ``value`` departs from ``schema``, as human-readable paths.

    Returns an empty list for a conforming value. The list is capped: the caller uses it
    to repair a response or to record why one was rejected, and neither needs the
    hundredth violation.
    """
    violations: list[str] = []
    _collect(value, schema, path, violations)
    return violations[:MAX_VIOLATIONS]


def conforms(value: Any, schema: dict) -> bool:
    return not schema_violations(value, schema)


def _collect(value: Any, schema: dict, path: str, out: list[str]) -> None:
    if len(out) >= MAX_VIOLATIONS or not isinstance(schema, dict):
        return

    expected = schema.get("type")
    if isinstance(expected, str):
        check = _TYPE_CHECKS.get(expected)
        if check and not check(value):
            out.append(f"{path}: expected {expected}, got {type(value).__name__}")
            return

    enum = schema.get("enum")
    if isinstance(enum, list) and value not in enum:
        out.append(f"{path}: {value!r} is not one of {enum}")
        return

    if isinstance(value, int) and not isinstance(value, bool):
        minimum, maximum = schema.get("minimum"), schema.get("maximum")
        if minimum is not None and value < minimum:
            out.append(f"{path}: {value} below minimum {minimum}")
        if maximum is not None and value > maximum:
            out.append(f"{path}: {value} above maximum {maximum}")

    if isinstance(value, dict):
        properties = schema.get("properties") or {}
        for key in schema.get("required") or []:
            if key not in value:
                out.append(f"{path}: missing required key {key!r}")
        if schema.get("additionalProperties") is False:
            for key in value:
                if key not in properties:
                    out.append(f"{path}: unexpected key {key!r}")
        for key, sub_schema in properties.items():
            if key in value and isinstance(sub_schema, dict):
                _collect(value[key], sub_schema, f"{path}.{key}", out)

    elif isinstance(value, list):
        item_schema = schema.get("items")
        if isinstance(item_schema, dict):
            for index, item in enumerate(value):
                if len(out) >= MAX_VIOLATIONS:
                    return
                _collect(item, item_schema, f"{path}[{index}]", out)


def describe_schema(schema: dict, indent: int = 0) -> str:
    """The schema as a compact outline, for a backend that will not enforce it.

    A raw JSON Schema dump is mostly punctuation the model has to parse before it learns
    anything; this states the keys, their types and their constraints in the order they
    must be generated.
    """
    lines: list[str] = []
    _describe(schema, indent, lines)
    return "\n".join(lines)


def _describe(schema: dict, indent: int, lines: list[str]) -> None:
    pad = "  " * indent
    properties = schema.get("properties") or {}
    required = set(schema.get("required") or [])
    for key, sub in properties.items():
        if not isinstance(sub, dict):
            continue
        kind = sub.get("type", "any")
        notes = [] if key in required else ["optional"]
        if sub.get("enum"):
            notes.append("one of " + "|".join(str(e) for e in sub["enum"]))
        if sub.get("minimum") is not None or sub.get("maximum") is not None:
            notes.append(f"{sub.get('minimum', '-∞')}..{sub.get('maximum', '∞')}")
        suffix = f"  ({', '.join(notes)})" if notes else ""
        if kind == "array":
            item = sub.get("items") or {}
            item_kind = item.get("type", "any") if isinstance(item, dict) else "any"
            lines.append(f"{pad}- {key}: array of {item_kind}{suffix}")
            if item_kind == "object":
                _describe(item, indent + 1, lines)
        else:
            lines.append(f"{pad}- {key}: {kind}{suffix}")
            if kind == "object":
                _describe(sub, indent + 1, lines)

"""What the question actually asks for, condition by condition, and what closed each one.

A benchmark question is a conjunction: born in 1886, travelled April to November, was
mistaken for a shaman. Nothing in the run held the idea of *a condition with a status*.
There were thirty list-shaped keys in search memory and a scratchpad, and what reached
the prompt was ``scratchpad[-2500:]`` — so run memory was lost precisely in the middle,
exactly when a question had taken enough steps for the middle to matter. A round could
therefore go looking again for something an earlier round had already established, and
nothing in the state could contradict it.

The registry is a projection, not a second store. Conditions are the numbered
``completion_criteria`` the requirements node already produces, and their statuses are
read off the evidence-ledger rows that already index against those same numbers. Nothing
here can drift from the ledger, because there is nothing here to drift: it is the ledger,
read by condition instead of by claim. It is small enough to send whole.
"""

from dataclasses import dataclass, field

from .sources import _normalize_source_url

# Strongest first. A condition with both a supporting and a rejecting row is reported as
# settled rather than open — the disagreement is visible in the rows themselves, and
# treating it as open sends the run searching for something it has already decided twice.
_STATUS_PRECEDENCE = ("satisfied", "refuted", "partial", "open")

_STATUS_MARK = {
    "satisfied": "OK  ",
    "refuted": "NO  ",
    "partial": "PART",
    "open": "??  ",
}


@dataclass
class Constraint:
    """One condition from the question, and what settled it."""

    index: int
    text: str
    status: str = "open"
    source_urls: list[str] = field(default_factory=list)
    # The claim the ledger recorded for this condition — what the run believes it read.
    quote: str = ""

    def as_dict(self) -> dict:
        return {
            "index": self.index,
            "text": self.text,
            "status": self.status,
            "source_urls": list(self.source_urls),
            "quote": self.quote,
        }


def _row_status(row: dict) -> str:
    status = str(row.get("support_status") or "").strip().lower()
    if status == "rejected":
        return "refuted"
    if status == "supported" and row.get("can_use_in_answer"):
        return "satisfied"
    if status in ("supported", "partial"):
        return "partial"
    return "open"


def build_registry(
    completion_criteria: list[str],
    ledger_result: dict | None,
    candidate_sources: list[dict] | None = None,
) -> list[dict]:
    """Project the ledger onto the question's conditions."""
    registry = [
        Constraint(index=index, text=str(text))
        for index, text in enumerate(completion_criteria or [])
    ]
    if not registry:
        return []

    sources = list(candidate_sources or [])
    ledger_result = ledger_result if isinstance(ledger_result, dict) else {}
    for row in ledger_result.get("ledger", []) or []:
        if not isinstance(row, dict):
            continue
        index = row.get("requirement_index")
        if not isinstance(index, int) or not (0 <= index < len(registry)):
            continue
        constraint = registry[index]
        status = _row_status(row)
        if _STATUS_PRECEDENCE.index(status) < _STATUS_PRECEDENCE.index(
            constraint.status
        ):
            constraint.status = status
            constraint.quote = str(row.get("proposed_claim") or "")[:300]
        for source_id in row.get("source_ids", []) or []:
            if not isinstance(source_id, int) or not (1 <= source_id <= len(sources)):
                continue
            source = sources[source_id - 1]
            url = _normalize_source_url(
                str(source.get("url") or "") if isinstance(source, dict) else ""
            )
            if url and url not in constraint.source_urls:
                constraint.source_urls.append(url)

    return [constraint.as_dict() for constraint in registry]


def open_constraints(registry: list[dict] | None) -> list[dict]:
    """Conditions nothing has settled yet — the only ones more searching can help."""
    return [
        item
        for item in registry or []
        if isinstance(item, dict) and item.get("status") in ("open", "partial")
    ]


def all_settled(registry: list[dict] | None) -> bool:
    return bool(registry) and not open_constraints(registry)


def format_for_prompt(registry: list[dict] | None, max_quote_chars: int = 160) -> str:
    """The whole registry, compactly. Sent in full because it fits in full.

    The scratchpad tail cannot say which conditions are already closed — it says what the
    last few steps printed. This says what the run knows, and by which page it knows it.
    """
    if not registry:
        return "(no conditions extracted)"
    lines = []
    for item in registry:
        if not isinstance(item, dict):
            continue
        mark = _STATUS_MARK.get(str(item.get("status")), "??  ")
        line = f"  [{mark}] {item.get('index')}. {item.get('text')}"
        quote = str(item.get("quote") or "").strip()
        if quote:
            line += f"\n         claim: {quote[:max_quote_chars]}"
        urls = item.get("source_urls") or []
        if urls:
            line += f"\n         from:  {', '.join(str(url) for url in urls[:3])}"
        lines.append(line)
    return "\n".join(lines)
